    });
  },
  methods: {
    // 对象转数组
    objToArr(data) {
      let obj = Object.keys(data);
      let m = obj.map((key) => data[key]);
      return m;
    },
    setConfig(data) {
      if (!data) return;
      if (data.mbConfig) {
        this.menuStyleConfig = data.menuStyleConfig.tabVal;
        this.showConfig = data.showConfig.tabVal;
        this.filletImg = data.filletImg.type;
        this.filletValImg = data.filletImg.val;
        this.valListImg = data.filletImg.valList;
        this.fillet = data.fillet.type;
        this.filletVal = data.fillet.val;
        this.valList = data.fillet.valList;
        this.toneConfig = data.toneConfig.tabVal;
        this.pointerColor = data.pointerColor.color[0].item;
        this.pointerBgColor = data.pointerBgColor.color[0].item;
        this.bottomBgColor = data.bottomBgColor.color[0].item;
        this.slider = data.mbConfig.val;
        this.prConfig = data.prConfig.val;
        this.topConfig = data.topConfig.val;
        this.bottomConfig = data.bottomConfig.val;
        this.bgColorLeft = data.bgColor.color[0].item;
        this.bgColorRight = data.bgColor.color[1].item;
        let rowsNum = data.rowsNum.tabVal;
        let number = data.number.tabVal;
        let lists = this.objToArr(data.menuConfig.list);
        let list = [];
        lists.forEach((item) => {
          if (item.show) {
            list.push(item);
          }
        });
        this.number = number;
        this.rowsNum = rowsNum;
        let vuexMenu = [];
        if (this.showConfig) {
          if (rowsNum === 0) {
            if (number === 0) {
              vuexMenu = list.splice(0, 3);
            } else if (number === 1) {
              vuexMenu = list.splice(0, 4);
            } else if (number === 2) {
              vuexMenu = list.splice(0, 5);
            }
          } else if (rowsNum === 1) {
            if (number === 0) {
              vuexMenu = list.splice(0, 6);
            } else if (number === 1) {
              vuexMenu = list.splice(0, 8);
            } else if (number === 2) {
              vuexMenu = list.splice(0, 10);
            }
          } else if (rowsNum === 2) {
            if (number === 0) {
              vuexMenu = list.splice(0, 9);
            } else if (number === 1) {
              vuexMenu = list.splice(0, 12);
            } else {
              vuexMenu = list.splice(0, 15);
            }
          } else {
            if (number === 0) {
              vuexMenu = list.splice(0, 12);
            } else if (number === 1) {
              vuexMenu = list.splice(0, 16);
            } else {
              vuexMenu = list.splice(0, 20);
            }
          }
          this.vuexMenu = vuexMenu;
        } else {
          this.vuexMenu = lists;
        }
      }
    },
